import { useId } from "react";

import { Label } from "@/components/ui/label";
import {
	Select,
	SelectContent,
	SelectGroup,
	SelectItem,
	SelectLabel,
	SelectTrigger,
	SelectValue,
} from "@/components/ui/select";

import { cn } from "../utilities/cn";

const Square = ({
	className,
	children,
}: {
	className?: string;
	children: React.ReactNode;
}) => (
	<span
		data-square
		className={cn(
			"bg-muted text-muted-foreground flex size-5 items-center justify-center rounded text-xs font-medium",
			className
		)}
		aria-hidden="true"
	>
		{children}
	</span>
);

export default function Component() {
	const id = useId();
	return (
		<div className="*:not-first:mt-2">
			<Label htmlFor={id}>Options with placeholder avatar</Label>
			<Select defaultValue="1">
				<SelectTrigger
					id={id}
					className="ps-2 [&>span]:flex [&>span]:items-center [&>span]:gap-2 [&>span_[data-square]]:shrink-0"
				>
					<SelectValue placeholder="Select framework" />
				</SelectTrigger>
				<SelectContent className="[&_*[role=option]]:ps-2 [&_*[role=option]]:pe-8 [&_*[role=option]>span]:start-auto [&_*[role=option]>span]:end-2 [&_*[role=option]>span]:flex [&_*[role=option]>span]:items-center [&_*[role=option]>span]:gap-2">
					<SelectGroup>
						<SelectLabel className="ps-2">Impersonate user</SelectLabel>
						<SelectItem value="1">
							<Square className="bg-indigo-400/20 text-indigo-500">
								F
							</Square>
							<span className="truncate">Frank Morris</span>
						</SelectItem>
						<SelectItem value="2">
							<Square className="bg-purple-400/20 text-purple-500">
								X
							</Square>
							<span className="truncate">Xavier Guerra</span>
						</SelectItem>
						<SelectItem value="3">
							<Square className="bg-rose-400/20 text-rose-500">A</Square>
							<span className="truncate">Anne Kelley</span>
						</SelectItem>
					</SelectGroup>
				</SelectContent>
			</Select>
		</div>
	);
}

"use client";

import React from "react";

import { cn } from "@/registry/utilities/cn";
import * as LabelPrimitive from "@radix-ui/react-label";
import { cva, type VariantProps } from "class-variance-authority";

const labelVariants = cva(
	"text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
);

const Label = React.forwardRef<
	React.ElementRef<typeof LabelPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof LabelPrimitive.Root> &
		VariantProps<typeof labelVariants>
>(({ className, ...props }, ref) => (
	<LabelPrimitive.Root
		ref={ref}
		className={cn(labelVariants(), className)}
		{...props}
	/>
));
Label.displayName = LabelPrimitive.Root.displayName;

export { Label };

import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}
